@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun EditProfileDialog(
    profile: Profile,
    onDismiss: () -> Unit,
    onSave: (Profile) -> Unit,
    onDelete: (Profile) -> Unit,
) {
    var name by remember { mutableStateOf(profile.name) }
    var kind by remember { mutableStateOf(profile.kind) }
    var phoneNumber by remember { mutableStateOf(profile.phoneNumber.orEmpty()) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(stringResource(R.string.edit_profile_title)) },
        text = {
            Column {
                OutlinedTextField(
                    value = name,
                    onValueChange = { name = it },
                    label = { Text(stringResource(R.string.name_label)) },
                    modifier = Modifier.fillMaxWidth(),
                )
                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier.padding(top = 8.dp),
                ) {
                    FilterChip(
                        selected = kind == ProfileKind.PERSON,
                        onClick = { kind = ProfileKind.PERSON },
                        label = { Text(stringResource(R.string.person)) },
                        border = FilterChipDefaults.filterChipBorder(
                            enabled = true,
                            selected = kind == ProfileKind.PERSON,
                            borderColor = MaterialTheme.colorScheme.outline,
                            selectedBorderColor = IconOrange,
                            borderWidth = 1.dp,
                            selectedBorderWidth = 2.dp,
                        ),
                    )
                    FilterChip(
                        selected = kind == ProfileKind.PET,
                        onClick = { kind = ProfileKind.PET },
                        label = { Text(stringResource(R.string.pet)) },
                        border = FilterChipDefaults.filterChipBorder(
                            enabled = true,
                            selected = kind == ProfileKind.PET,
                            borderColor = MaterialTheme.colorScheme.outline,
                            selectedBorderColor = IconOrange,
                            borderWidth = 1.dp,
                            selectedBorderWidth = 2.dp,
                        ),
                    )
                }
                OutlinedTextField(
                    value = phoneNumber,
                    onValueChange = { phoneNumber = it },
                    label = { Text(stringResource(R.string.caregiver_phone_label)) },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 8.dp),
                )
            }
        },
        confirmButton = {
            Row {
                TextButton(
                    onClick = { onDelete(profile) },
                    colors = ButtonDefaults.textButtonColors(
                        contentColor = MaterialTheme.colorScheme.error,
                    ),
                ) {
                    Text(stringResource(R.string.delete))
                }
                TextButton(
                    onClick = {
                        if (name.isNotBlank()) {
                            onSave(
                                profile.copy(
                                    name = name,
                                    kind = kind,
                                    phoneNumber = phoneNumber.ifBlank { null },
                                ),
                            )
                        }
                    },
                ) {
                    Text(stringResource(R.string.save))
                }
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text(stringResource(R.string.cancel)) }
        },
    )
}
